#!/usr/bin/env python3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
APP = ROOT / 'src/App.tsx'
FORM = ROOT / 'src/components/Editor/ReportEditorForm.tsx'
MODAL = ROOT / 'src/components/Editor/StepEditorModal.tsx'


def require(text: str, marker: str, label: str) -> None:
    if marker not in text:
        raise SystemExit(f'Missing expected marker for {label}: {marker[:80]}')


def build_modal() -> None:
    s = FORM.read_text(encoding='utf-8')
    s = s.replace("import React, { useState } from 'react';", "import React, { useState, useEffect } from 'react';")
    start = s.index('interface EditorProps')
    logic_start = s.index('  const updateField', start)
    logic = s[logic_start:s.index('  return (', logic_start)]
    body_start = s.index('      {/* Form Content Area */}')
    body_open_end = s.index('        {/* =========================================================================', body_start)
    body_content = s[body_open_end:s.index('      {/* Bottom Step Navigation Bar', body_open_end)]
    last_close = body_content.rfind('      </div>')
    if last_close < 0:
        raise SystemExit('Could not locate ReportEditorForm content wrapper ending')
    body_content = body_content[:last_close]

    prefix = s[:start]
    prefix = prefix.replace("import { EMPTY_REPORT_DATA, SAMPLE_REPORT_DATA } from '../../data/presets';\n", '')

    modal = prefix + '''interface StepEditorModalProps {\n  isOpen: boolean;\n  onClose: () => void;\n  initialStep?: number;\n  data: ReportData;\n  onChange: (newData: ReportData) => void;\n  onComplete?: () => void;\n}\n\nexport const StepEditorModal: React.FC<StepEditorModalProps> = ({\n  isOpen, onClose, initialStep = 0, data, onChange, onComplete,\n}) => {\n  const [currentStep, setCurrentStep] = useState<number>(initialStep);\n  const [customDirectorateMode, setCustomDirectorateMode] = useState(\n    Boolean(data.directorate && !SAUDI_DIRECTORATES.includes(data.directorate))\n  );\n\n  useEffect(() => { if (isOpen) setCurrentStep(initialStep); }, [isOpen, initialStep]);\n  useEffect(() => {\n    if (!isOpen) return;\n    const previousOverflow = document.body.style.overflow;\n    document.body.style.overflow = 'hidden';\n    return () => { document.body.style.overflow = previousOverflow; };\n  }, [isOpen]);\n\n  if (!isOpen) return null;\n\n''' + logic + '''  const handleNext = () => {\n    if (currentStep < 4) setCurrentStep((step) => step + 1);\n    else { onComplete?.(); onClose(); }\n  };\n\n  return (\n    <div className="fixed inset-0 z-[90] bg-slate-950/75 backdrop-blur-sm flex items-center justify-center p-2 sm:p-4" dir="rtl" role="dialog" aria-modal="true">\n      <div className="bg-white w-full max-w-3xl h-[min(92dvh,860px)] rounded-3xl shadow-2xl border border-slate-200 overflow-hidden flex flex-col text-right">\n        <div className="bg-gradient-to-l from-emerald-950 via-emerald-900 to-teal-950 text-white p-3.5 sm:p-5 shrink-0">\n          <div className="flex items-center justify-between gap-3 mb-3">\n            <div className="flex items-center gap-3 min-w-0">\n              <div className="w-10 h-10 rounded-2xl bg-amber-400 text-emerald-950 font-black text-sm flex items-center justify-center shadow-md shrink-0">{currentStep + 1}</div>\n              <div className="min-w-0">\n                <span className="text-[10px] font-black bg-amber-400/20 text-amber-300 border border-amber-400/40 px-2.5 py-0.5 rounded-full">{stepsConfig[currentStep].kicker}</span>\n                <h2 className="text-sm sm:text-base font-black text-white mt-1 truncate">{stepsConfig[currentStep].title}</h2>\n                <p className="text-[10px] text-emerald-100/80 font-bold truncate">{stepsConfig[currentStep].desc}</p>\n              </div>\n            </div>\n            <button type="button" onClick={onClose} className="w-9 h-9 rounded-full bg-white/10 hover:bg-white/20 text-white flex items-center justify-center shrink-0" aria-label="إغلاق"><X className="w-5 h-5" /></button>\n          </div>\n          <div className="h-1.5 rounded-full bg-emerald-950/70 overflow-hidden border border-emerald-800 mb-3">\n            <div className="h-full bg-amber-400 transition-all duration-300" style={{ width: `${((currentStep + 1) / 5) * 100}%` }} />\n          </div>\n          <div className="flex items-center gap-1.5 overflow-x-auto no-scrollbar">\n            {stepsConfig.map((step, idx) => {\n              const active = currentStep === idx;\n              const done = currentStep > idx;\n              return (\n                <button key={step.id} type="button" onClick={() => setCurrentStep(idx)} className={`py-1.5 px-2.5 sm:px-3 rounded-xl text-[10px] sm:text-[11px] font-bold whitespace-nowrap flex items-center gap-1.5 shrink-0 ${active ? 'bg-amber-400 text-emerald-950 shadow-sm' : done ? 'bg-emerald-800 text-white' : 'bg-emerald-950/55 text-emerald-100 border border-emerald-800/70'}`}>\n                  <span className={`w-4 h-4 rounded-full text-[9px] font-black flex items-center justify-center ${active ? 'bg-emerald-950 text-amber-400' : 'bg-emerald-700 text-white'}`}>{done ? '✓' : idx + 1}</span>\n                  <span>{step.title}</span>\n                </button>\n              );\n            })}\n          </div>\n        </div>\n\n        <div className="flex-1 overflow-y-auto overscroll-contain p-4 sm:p-6 text-xs bg-white">\n''' + body_content + '''\n        </div>\n\n        <div className="p-3 sm:p-4 bg-slate-50 border-t border-slate-200 flex items-center justify-between gap-2 shrink-0">\n          <button type="button" onClick={onClose} className="px-3.5 py-2.5 rounded-xl bg-white border border-slate-300 text-slate-700 hover:bg-slate-100 text-xs font-bold">إغلاق</button>\n          <div className="flex items-center gap-2 min-w-0">\n            {currentStep > 0 && <button type="button" onClick={() => setCurrentStep((step) => Math.max(0, step - 1))} className="px-3.5 py-2.5 rounded-xl bg-white border border-slate-300 text-slate-800 text-xs font-bold flex items-center gap-1.5"><ArrowRight className="w-4 h-4" /><span>السابق</span></button>}\n            <button type="button" onClick={handleNext} className={`px-4 sm:px-5 py-2.5 rounded-xl active:scale-95 text-xs font-black flex items-center gap-2 shadow-md transition-all ${currentStep < 4 ? 'bg-emerald-800 hover:bg-emerald-900 text-white' : 'bg-amber-400 hover:bg-amber-300 text-emerald-950'}`}>\n              {currentStep < 4 ? <><span className="hidden sm:inline">الانتقال للخطوة التالية ({stepsConfig[currentStep + 1].title})</span><span className="sm:hidden">الخطوة التالية</span><ArrowLeft className="w-4 h-4 text-amber-300" /></> : <><CheckCircle2 className="w-4 h-4" /><span>إتمام جميع الخطوات وإغلاق القائمة</span></>}\n            </button>\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n};\n'''
    MODAL.write_text(modal, encoding='utf-8')


def patch_app() -> None:
    s = APP.read_text(encoding='utf-8')
    require(s, "import { ReportEditorForm } from './components/Editor/ReportEditorForm';", 'App editor import')
    s = s.replace("import { ReportEditorForm } from './components/Editor/ReportEditorForm';", "import { StepEditorModal } from './components/Editor/StepEditorModal';")
    require(s, '  PenTool,\n', 'App icon import')
    s = s.replace('  PenTool,\n', '  PenTool,\n  School,\n  Target,\n  PieChart,\n  Camera,\n  ArrowLeft,\n', 1)

    needle = "  const [exportDropdownOpen, setExportDropdownOpen] = useState<boolean>(false);\n"
    require(s, needle, 'modal state insertion')
    s = s.replace(needle, needle + "  const [isStepModalOpen, setIsStepModalOpen] = useState<boolean>(false);\n  const [activeModalStep, setActiveModalStep] = useState<number>(0);\n", 1)
    s = s.replace('  // Save to LocalStorage\n', "  const openStepModal = (stepIndex: number = 0) => { setActiveModalStep(stepIndex); setIsStepModalOpen(true); };\n\n  // Save to LocalStorage\n", 1)

    t0 = s.index("  const templates: { id: TemplateId; label: string; number: number }[] = [")
    t1 = s.index('  ];', t0) + 4
    steps = """\n\n  const stepsNav = [\n    { id: 0, title: 'هوية الجهة', hint: 'المنشأة والشعار والاعتماد', icon: School },\n    { id: 1, title: 'بيانات التقرير', hint: 'العنوان والتاريخ والمقر', icon: FileText },\n    { id: 2, title: 'المحتوى والأثر', hint: 'الأهداف والتنفيذ والنتائج', icon: Target },\n    { id: 3, title: 'المؤشرات الرقمية', hint: 'الأرقام والإحصائيات والرضا', icon: PieChart },\n    { id: 4, title: 'الشواهد والاعتماد', hint: 'الصور والتوقيعات والاعتماد', icon: Camera },\n  ];\n"""
    s = s[:t1] + steps + s[t1:]

    h0 = s.index('          {/* WASM Official Brand */}')
    h1 = s.index('          {/* Desktop Center Template Switcher */}', h0)
    header = '''          {/* الهوية + أقرب زر للتصدير والطباعة */}\n          <div className="flex items-center gap-2 sm:gap-3 shrink-0">\n            <div className="relative" ref={exportDropdownRef}>\n              <button type="button" onClick={() => setExportDropdownOpen((open) => !open)} disabled={isExporting} title="تصدير وطباعة التقرير" className="px-3 sm:px-3.5 py-2 rounded-xl bg-emerald-800 hover:bg-emerald-900 active:scale-95 text-white text-[10.5px] sm:text-xs font-black flex items-center gap-1.5 shadow-md disabled:opacity-50 min-h-[38px]">\n                <Download className="w-4 h-4 text-amber-300 shrink-0" /><span className="hidden sm:inline">تصدير وطباعة التقرير</span><span className="sm:hidden">تصدير وطباعة</span><ChevronDown className={`w-3.5 h-3.5 text-amber-300 transition-transform ${exportDropdownOpen ? 'rotate-180' : ''}`} />\n              </button>\n              {exportDropdownOpen && <div className="absolute right-0 top-full mt-1.5 w-72 max-w-[calc(100vw-16px)] bg-white rounded-2xl shadow-2xl border border-slate-200 py-2 z-[70] text-right" dir="rtl">\n                <div className="px-3 pb-2 mb-1 border-b border-slate-100 text-[10px] font-black text-slate-400">الطباعة والتصدير</div>\n                <button type="button" onClick={handlePrint} className="w-full px-3 py-2.5 hover:bg-emerald-50 flex items-center gap-2.5 text-right"><span className="w-9 h-9 rounded-xl bg-emerald-800 text-amber-300 flex items-center justify-center shrink-0"><Printer className="w-4 h-4" /></span><span><strong className="block text-xs text-emerald-950">طباعة A4 فورية</strong><small className="text-[10px] text-slate-500">طباعة مباشرة بقياس A4 الرسمي</small></span></button>\n                <button type="button" onClick={() => { setExportDropdownOpen(false); void handleExportPDF(); }} className="w-full px-3 py-2.5 hover:bg-emerald-50 flex items-center gap-2.5 text-right border-t border-slate-100"><span className="w-9 h-9 rounded-xl bg-emerald-100 text-emerald-800 flex items-center justify-center shrink-0"><Download className="w-4 h-4" /></span><span><strong className="block text-xs text-slate-800">تصدير ملف PDF جاهز للطباعة</strong><small className="text-[10px] text-slate-500">ملف A4 عالي الجودة</small></span></button>\n                <button type="button" onClick={() => { setExportDropdownOpen(false); void handleExportImage(); }} className="w-full px-3 py-2.5 hover:bg-blue-50 flex items-center gap-2.5 text-right border-t border-slate-100"><span className="w-9 h-9 rounded-xl bg-blue-100 text-blue-800 flex items-center justify-center shrink-0"><FileImage className="w-4 h-4" /></span><span><strong className="block text-xs text-slate-800">تصدير صورة PNG عالية الدقة</strong><small className="text-[10px] text-slate-500">للمشاركة والواتساب وقنوات التواصل</small></span></button>\n              </div>}\n            </div>\n            <div className="flex items-center gap-2.5 min-w-0">\n              <img src="/icons/icon-512.png" alt="وَسْم" className="wasm-brand-icon w-9 h-9 sm:w-10 sm:h-10 rounded-xl shadow-sm shrink-0" />\n              <div className="min-w-0 hidden xs:block"><h1 className="text-sm sm:text-base font-black text-[#08211e] leading-none">وَسْم</h1><p className="wasm-tagline-chip mt-1 inline-flex items-center gap-1.5 rounded-lg px-2 py-0.5 text-[8.5px] sm:text-[9.5px] font-bold whitespace-nowrap"><span className="wasm-tagline-cream">إنجازك في تقرير</span><span className="wasm-tagline-gold">يليق بأثره</span></p></div>\n            </div>\n          </div>\n\n'''
    s = s[:h0] + header + s[h1:]

    a0 = s.index('            {/* Print Button */}')
    a1 = s.index('          </div>\n        </div>\n\n        {/* Mobile / Tablet View Switcher', a0)
    s = s[:a0] + '''            <button onClick={() => openStepModal(0)} title="فتح نموذج إدخال البيانات" className="p-2 sm:px-3 sm:py-1.5 rounded-xl bg-amber-50 hover:bg-amber-100 text-emerald-950 border border-amber-200 text-xs font-black flex items-center gap-1.5 min-h-[38px]"><PenTool className="w-4 h-4 text-emerald-800" /><span className="hidden sm:inline">إدخال البيانات</span></button>\n''' + s[a1:]

    old = '''        <div\n          className={`no-print lg:col-span-5 ${\n            mobileTab === 'editor' ? 'block' : 'hidden lg:block'\n          } h-[calc(100vh-145px)] lg:h-[calc(100vh-105px)]`}\n        >\n          <ReportEditorForm data={reportData} onChange={setReportData} />\n        </div>\n'''
    require(s, old, 'editor panel replacement')
    panel = '''        <div className={`no-print lg:col-span-5 ${mobileTab === 'editor' ? 'block' : 'hidden lg:block'} h-auto lg:h-[calc(100vh-105px)]`}>\n          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm h-full p-3 sm:p-4 flex flex-col overflow-hidden">\n            <div className="shrink-0 mb-3 flex items-center justify-between gap-2"><div><h2 className="text-sm font-black text-emerald-950">إدخال بيانات التقرير</h2><p className="text-[10px] sm:text-[11px] text-slate-500 font-semibold mt-0.5">اختر الخطوة؛ ستفتح نافذة مخصصة لبياناتها فقط.</p></div><span className="text-[10px] font-black text-emerald-800 bg-emerald-50 border border-emerald-200 rounded-full px-2.5 py-1">5 خطوات</span></div>\n            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 gap-2.5 flex-1 content-start">\n              {stepsNav.map((step) => { const Icon = step.icon; return <button key={step.id} type="button" onClick={() => openStepModal(step.id)} className="group w-full p-3.5 rounded-2xl bg-slate-50 hover:bg-emerald-50 border border-slate-200 hover:border-emerald-300 text-right flex items-center gap-3 transition-all active:scale-[0.99]"><span className="w-10 h-10 rounded-2xl bg-emerald-800 text-white flex items-center justify-center font-black shadow-sm shrink-0 group-hover:bg-emerald-900">{step.id + 1}</span><span className="min-w-0 flex-1"><strong className="block text-xs sm:text-sm font-black text-emerald-950">{step.title}</strong><small className="block text-[10px] text-slate-500 font-semibold mt-0.5 truncate">{step.hint}</small></span><Icon className="w-5 h-5 text-emerald-700 shrink-0" /><ArrowLeft className="w-4 h-4 text-slate-300 group-hover:text-amber-500 shrink-0" /></button>; })}\n            </div>\n            <div className="mt-3 pt-3 border-t border-slate-200 shrink-0 text-[10px] text-slate-500 font-semibold leading-relaxed">لا يوجد نموذج طويل في الصفحة الرئيسية. التنقل يتم داخل النافذة من 1 ← 2 ← 3 ← 4 ← 5.</div>\n          </div>\n        </div>\n'''
    s = s.replace(old, panel, 1)

    print_marker = '      {/* Dedicated Clean Print Container - Rendered ONLY during browser window.print() */}\n'
    require(s, print_marker, 'modal mount')
    modal_mount = '''      <StepEditorModal isOpen={isStepModalOpen} onClose={() => setIsStepModalOpen(false)} initialStep={activeModalStep} data={reportData} onChange={setReportData} onComplete={() => { localStorage.setItem('waththiq_report_data', JSON.stringify(reportData)); setSaveToast('اكتملت خطوات التقرير وحُفظت البيانات محلياً.'); setTimeout(() => setSaveToast(''), 3000); }} />\n\n'''
    s = s.replace(print_marker, modal_mount + print_marker, 1)
    APP.write_text(s, encoding='utf-8')


build_modal()
patch_app()
print('Interactive five-step modal flow and consolidated export menu applied.')
